#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

typedef vector<vector<int>> Grid;

// Independent insertion-sort oracle: first each row, then each column.
Grid expectedGrid(Grid a) {
    int n = a.size(), m = a[0].size();
    for (int row = 0; row < n; ++row)
        for (int col = 1; col < m; ++col) {
            int value = a[row][col], j = col;
            while (j && a[row][j - 1] > value) {
                a[row][j] = a[row][j - 1]; --j;
            }
            a[row][j] = value;
        }
    for (int col = 0; col < m; ++col)
        for (int row = 1; row < n; ++row) {
            int value = a[row][col], j = row;
            while (j && a[j - 1][col] > value) {
                a[j][col] = a[j - 1][col]; --j;
            }
            a[j][col] = value;
        }
    return a;
}

string format(const Grid &a) {
    ostringstream text;
    for (const auto &row : a) {
        for (size_t col = 0; col < row.size(); ++col)
            text << (col ? " " : "") << row[col];
        text << '\n';
    }
    return text.str();
}

int main(int argc, char *argv[]) {
    if (argc != 2) { cerr << "Usage: tester <student_executable>\n"; return 2; }
    string exe = argv[1];
    vector<Grid> tests = {
        {{6,5},{4,3},{2,1}},
        {{1,3,2,5},{6,2,4,4},{5,4,1,3}},
        {{4,3},{2,1}},
        {{5,5,1},{3,3,3}},
        {{9,1,8},{4,7,2},{6,5,3}},
        {{1,2,3,4},{9,8,7,6}},
        {{100,1},{1,100},{50,50}},
        {{7,7},{7,7}},
        {{10,1,2,3,4,5,6,7,8,9},{9,8,7,6,5,4,3,2,1,10}},
    };
    Grid longGrid(10, vector<int>(2));
    Grid square(10, vector<int>(10));
    Grid identical(10, vector<int>(10, 100));
    for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 2; ++j)
            longGrid[i][j] = 100 - ((i * 29 + j * 47) % 100);
        for (int j = 0; j < 10; ++j)
            square[i][j] = 1 + ((i * 73 + j * 29 + i * j * 13) % 100);
    }
    tests.push_back(longGrid);
    tests.push_back(square);
    tests.push_back(identical);
    int failed = 0;
    for (size_t caseNo = 0; caseNo < tests.size(); ++caseNo) {
        const Grid &original = tests[caseNo];
        Grid expected = expectedGrid(original);
        ofstream input("grid_test.in");
        input << original.size() << " " << original[0].size() << '\n'
              << format(original); input.close();
        int status = system(("\"" + exe + "\" < grid_test.in > grid_test.out 2>&1").c_str());
        ifstream output("grid_test.out");
        Grid actual = original;
        bool valid = true;
        for (auto &row : actual)
            for (int &value : row)
                if (!(output >> value)) valid = false;
        string extra;
        if (output >> extra) valid = false;
        if (status != 0 || !valid || actual != expected) {
            cout << "[FAIL] case " << caseNo + 1 << "\nInput:\n"
                 << original.size() << ' ' << original[0].size() << '\n' << format(original)
                 << "Expected:\n" << format(expected) << "Actual:\n";
            ifstream raw("grid_test.out");
            cout << raw.rdbuf() << '\n';
            ++failed;
        }
    }
    cout << "Ordered grid: " << tests.size() - failed << '/' << tests.size()
         << " cases passed\n";
    return failed ? 1 : 0;
}
